using System;using System.IO;using System.Linq;using System.Text;using System.Diagnostics;using System.Globalization;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Threading;using System.Web.Script.Serialization;
namespace SidebarAgentLifecycle {
 public static class EventStore {
  public static void Plain(string path){for(string p=Path.GetFullPath(path);!String.IsNullOrEmpty(p);p=Path.GetDirectoryName(p))if((File.Exists(p)||Directory.Exists(p))&&(File.GetAttributes(p)&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException();}
  public static bool Emit(string root,Receipt receipt){if(receipt==null||receipt.provider!="codex"&&receipt.provider!="claude-code")return false;string raw=new JavaScriptSerializer().Serialize(receipt);if(Lifecycle.ParseReceipt(raw,receipt.provider)==null)return false;string dir=Path.Combine(root,receipt.provider);Plain(dir);Directory.CreateDirectory(dir);string file=Path.Combine(dir,receipt.sessionHash+".json");Plain(file);bool held=false;using(var mutex=new Mutex(false,"Local\\SidebarAgent-"+receipt.sessionHash)){try{try{held=mutex.WaitOne(300);}catch(AbandonedMutexException){held=true;}if(!held)return false;Receipt previous=null;if(File.Exists(file)){if(new FileInfo(file).Length>4096)return false;previous=Lifecycle.ParseReceipt(File.ReadAllText(file),receipt.provider);if(previous==null)return false;}if(!Lifecycle.CanReplace(previous,receipt))return false;if(!File.Exists(file)&&Directory.EnumerateFiles(dir,"*.json").Take(1025).Count()>=1024)return false;string temporary=file+"."+Guid.NewGuid().ToString("N")+".tmp";File.WriteAllText(temporary,raw,new UTF8Encoding(false));if(File.Exists(file))File.Replace(temporary,file,null);else File.Move(temporary,file);return true;}finally{if(held)mutex.ReleaseMutex();}}}
 }
 public sealed class Owner {public int Pid;public DateTimeOffset Birth;public string Executable;}
 public static class AgentLifecyclePublisher {
  static readonly string Root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), @"StatusIsland\status-sources\agents");
  [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)]struct Entry {public uint Size,Usage,Pid;public IntPtr Heap;public uint Module,Threads,Parent;public int Priority;public uint Flags;[MarshalAs(UnmanagedType.ByValTStr,SizeConst=260)]public string Name;}
  [DllImport("kernel32.dll",SetLastError=true)]static extern IntPtr CreateToolhelp32Snapshot(uint flags,uint pid);
  [DllImport("kernel32.dll",CharSet=CharSet.Unicode)]static extern bool Process32First(IntPtr snapshot,ref Entry entry);
  [DllImport("kernel32.dll",CharSet=CharSet.Unicode)]static extern bool Process32Next(IntPtr snapshot,ref Entry entry);
  [DllImport("kernel32.dll")]static extern bool CloseHandle(IntPtr handle);
  static string Text(Dictionary<string,object> d,string key){object value;return d!=null&&d.TryGetValue(key,out value)?value as string:null;}
  static string ApprovedExecutable(string provider){string file=Path.Combine(Root,"connection.json");EventStore.Plain(file);if(!File.Exists(file)||new FileInfo(file).Length>8192)return null;var d=new JavaScriptSerializer{MaxJsonLength=8192,RecursionLimit=8}.DeserializeObject(File.ReadAllText(file)) as Dictionary<string,object>;object approved,providers;if(d==null||Text(d,"schema")!="sidebar.agent-connection.v1"||!d.TryGetValue("approved",out approved)||!(approved is bool)||!(bool)approved||!d.TryGetValue("providers",out providers))return null;var map=providers as Dictionary<string,object>;object details;if(map==null||!map.TryGetValue(provider,out details))return null;var spec=details as Dictionary<string,object>;string expected=Text(spec,"ownerExecutable");if(String.IsNullOrWhiteSpace(expected)||!Path.IsPathRooted(expected))return null;return Path.GetFullPath(expected);}
  static Owner FindOwner(string expected){IntPtr handle=CreateToolhelp32Snapshot(2,0);if(handle==new IntPtr(-1))return null;var parents=new Dictionary<int,int>();try{var entry=new Entry{Size=(uint)Marshal.SizeOf(typeof(Entry))};if(Process32First(handle,ref entry))do{parents[(int)entry.Pid]=(int)entry.Parent;}while(Process32Next(handle,ref entry));}finally{CloseHandle(handle);}int pid=Process.GetCurrentProcess().Id;for(int i=0;i<10;i++){int parent;if(!parents.TryGetValue(pid,out parent)||parent<=0)return null;pid=parent;using(var process=Process.GetProcessById(pid)){string path=process.MainModule.FileName;if(String.Equals(Path.GetFullPath(path),expected,StringComparison.OrdinalIgnoreCase))return new Owner{Pid=pid,Birth=new DateTimeOffset(process.StartTime.ToUniversalTime()),Executable=path};}}return null;}
  public static string ReadBoundedInput(Stream stream){using(var memory=new MemoryStream()){var bytes=new byte[4096];while(memory.Length<=262144){var read=stream.ReadAsync(bytes,0,bytes.Length);if(!read.Wait(500))return null;int n=read.Result;if(n==0)break;if(memory.Length+n>262144)return null;memory.Write(bytes,0,n);try{string ready=new UTF8Encoding(false,true).GetString(memory.ToArray());if(new JavaScriptSerializer{MaxJsonLength=262144,RecursionLimit=32}.DeserializeObject(ready) is Dictionary<string,object>)return ready;}catch{}}return new UTF8Encoding(false,true).GetString(memory.ToArray());}}
  public static int Main(string[]args){if(args.Length!=2||args[0]!="--capture"||(args[1]!="codex"&&args[1]!="claude-code")){Console.WriteLine("{\"mode\":\"plan-only\",\"hookInstalled\":false,\"networkRequests\":0,\"inputRead\":false,\"fileWrites\":0}");return 0;}string provider=args[1];try{EventStore.Plain(Root);string denied=Path.Combine(Root,provider+".access-denied");if(File.Exists(denied))return 0;string executable=ApprovedExecutable(provider);if(executable==null)return 0;var invocation=new DateTimeOffset(Process.GetCurrentProcess().StartTime.ToUniversalTime());Owner owner;try{owner=FindOwner(executable);}catch(UnauthorizedAccessException){File.WriteAllText(denied,"owner access denied; explicit repair required",new UTF8Encoding(false));return 0;}catch(System.ComponentModel.Win32Exception e){if(e.NativeErrorCode==5)File.WriteAllText(denied,"owner access denied; explicit repair required",new UTF8Encoding(false));return 0;}if(owner==null)return 0;if(!Console.IsInputRedirected)return 0;string input=ReadBoundedInput(Console.OpenStandardInput());Receipt receipt=Lifecycle.ParseInput(provider,input,owner.Pid,owner.Birth,owner.Executable,invocation);input=null;EventStore.Emit(Root,receipt);}catch{/* Hook errors never grant access, log payloads, retry another source or block the agent. */}return 0;}
 }
}
